describe('File Upload Functionality', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/upload');
  });

  it('should successfully upload a file and display confirmation', () => {
    // Create a dummy file for upload
    const testFile = new File(['content of test file'], 'test-document.pdf', { type: 'application/pdf' });

    // Upload the file by attaching it to the file input
    cy.get('[type="file"]').selectFile(testFile);

    // Verify the file name appears in the input field
    cy.get('[type="file"]').should('have.value', 'test-document.pdf');

    // Click the submit button
    cy.get('[type="submit"]').click();

    // Verify navigation to the success page
    cy.url().should('include', '/upload');

    // Verify success heading is displayed
    cy.get('[data-testid="success-heading"]').should('be.visible').should('contain', 'File Uploaded!');

    // Verify uploaded file name is displayed in the confirmation area
    cy.get('[data-testid="uploaded-file-name"]').should('be.visible').should('contain', 'test-document.pdf');

    // Verify the file preview is visible
    cy.get('[data-testid="file-preview"]').should('be.visible');
  });

  it('should handle file upload with invalid file type and display error', () => {
    // Create a dummy file with an invalid type
    const invalidFile = new File(['invalid content'], 'image.jpg', { type: 'image/jpeg' });

    // Upload the invalid file
    cy.get('[type="file"]').selectFile(invalidFile);

    // Click the submit button
    cy.get('[type="submit"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid file type');

    // Verify success heading is NOT displayed
    cy.get('[data-testid="success-heading"]').should('not.exist');

    // Verify uploaded file name is NOT displayed
    cy.get('[data-testid="uploaded-file-name"]').should('not.exist');

    // Verify the file input still has the invalid file selected
    cy.get('[type="file"]').should('have.value', 'image.jpg');
  });
});
